(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zu-sj-prepa-gyneco-j5-sfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zu-sj-prepa-gyneco-j5-sfm\",\n \"titre\": \"Préparation D.E (J) · J5 Gynéco-obstétrique SFM\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 50,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J5_Gyneco_SFM_Corrige_explique.pdf\",\n   \"sha256\": \"a85008fe20e77ed6b8adc1407b85a28dceca838bd302963937c9b14b4156a33f\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Gynéco-obstétrique · Prépa D.E J5 (SFM)\",\n     \"slug\": \"prepa-gyneco-j5-sfm\",\n     \"pages\": \"\",\n     \"count\": 50,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Gynéco-obstétrique\",\n     \"source\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans le placenta prævia associé à des métrorragies abondantes, la césarienne s'impose en urgence\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Devant un placenta prævia avec hémorragie importante (abondante ou continue), la conduite est l'évacuation utérine par césarienne en urgence au centre de référence, après mise en condition de la patiente.\\n\\nSource : SONU L3 (2024-2025), « CAT devant un placenta prævia » et « CAT devant une hémorragie en fin de grossesse »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La Présentation du front est une présentation céphalique où la tête est en hyperextension\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai ». Le cours définit la présentation du front comme une présentation céphalique avec une déflexion partielle (moyenne) de la tête ; la déflexion totale (maximale) correspond à la présentation de la face.\\n\\nSource : Cours Gynéco-Obstétrique 1re année INFAS, « Présentations fœtales »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La dessiccation est une complication survenant dans la procidence du cordon 2ème degré\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai ». La dessiccation (et le refroidissement) du cordon survient quand le cordon prolabé est exposé à l'air, ce qui comprime et lèse les vaisseaux. (explication hors cours du projet) Remarque : Dans ce même sujet (question 26), le degré où le cordon est extériorisé à la vulve est le degré III ; c'est à ce degré que la dessiccation est la plus marquée.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'épreuve du travail est une tentative d'accouchement par voie basse sur un bassin limite\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Faux ».\\n\\nSource : Gynécologie-Obstétrique L3, chap. 35 « L'épreuve du travail »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'autopalpation des seins est un moyen de prévention du cancer du sein qui est pratiqué par un personnel de soins qualifié\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'autopalpation des seins est faite par la femme elle-même (une fois par mois chez toute femme de plus de 20 ans). L'examen par un personnel qualifié s'appelle la palpation par le médecin.\\n\\nSource : Gynéco L2 IDE version 2025, « Le cancer du sein », Dépistage\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'échographie mammaire est l'examen radiologique à réaliser chez la femme jeune dans le cadre de la prévention du cancer du sein\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La mammographie est le seul examen complémentaire de dépistage de masse du cancer du sein (femmes à risque, femmes de 50 à 69 ans). L'échographie mammaire est un examen de diagnostic, pas l'examen de prévention.\\n\\nSource : Gynéco L2 IDE version 2025, « Le cancer du sein », Dépistage et Examens complémentaires\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le sexe est le premier facteur de risque du cancer du sein\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Être une femme est le principal facteur de risque du cancer du sein (environ 99 % des cas surviennent chez la femme), devant l'âge et les antécédents familiaux. (explication hors cours du projet) Remarque : La liste des facteurs de risque du cours (L2 IDE) ne cite pas le sexe.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La présentation de l'épaule négligée est la complication d'une présentation de l'épaule qui n'a pas été vite prise en charge\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'épaule négligée est l'aboutissement de toute présentation de l'épaule non prise en charge : membranes rompues, utérus rétracté, procidence d'un bras, fœtus le plus souvent mort pendant le travail.\\n\\nSource : Cours Gynéco-Obstétrique 1re année INFAS, « Présentations fœtales », Présentation de l'épaule négligée\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la Présentation du siège complet, on peut percevoir les pieds du fœtus dans l'aire de dilatation\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans le siège complet, le fœtus est assis en tailleur : au toucher on perçoit les fesses et les pieds. Dans le siège décomplété (mode des fesses), on ne perçoit que les fesses.\\n\\nSource : SONU L3 (2024-2025), « Accouchement du siège » ; Cours de soins obstétricaux 2e année SF, « Présentation du siège »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'accrochage des mentons au cours d'un accouchement gémellaire peut survenir si J1 est en présentation céphalique et J2 en présentation de siège\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'accrochage des mentons survient quand J1 est en siège et J2 en présentation céphalique : la tête dernière de J1 s'accroche à la tête de J2 qui s'engage. Avec J1 céphalique et J2 en siège, il n'y a pas d'accrochage.\\n\\nSource : SONU L3 (2024-2025), « Accouchement gémellaire », Complications particulières\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'autopalpation des seins se fait chaque trimestre par la femme elle-même\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'autopalpation se fait une fois par mois (de préférence après les règles), et non chaque trimestre.\\n\\nSource : Gynéco L2 IDE version 2025, « Le cancer du sein », Dépistage\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La manœuvre de Farabœuf est la plus utilisée pour faire le diagnostic de l'engagement\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Au toucher vaginal, le signe de Farabeuf est le plus couramment utilisé : la présentation est engagée si les deux doigts vaginaux ne peuvent pas passer entre la présentation et la concavité sacrée.\\n\\nSource : Gynécologie-Obstétrique L3, « Diagnostic de l'engagement » ; Cours Gynéco-Obstétrique 1re année INFAS, « Mécanisme de l'accouchement »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La première étiologie de l'hémorragie du post partum immédiat est l'atonie utérine\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours demande de penser systématiquement à l'atonie utérine devant toute HPPI ; c'est la première cause (le « T » du Tonus dans les 4 T).\\n\\nSource : Gynécologie-Obstétrique L3, « CAT devant une hémorragie du post-partum »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le cancer du sein est un cancer non hormono-dépendant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cancer du sein est un cancer en partie hormono-dépendant (et en partie lié à l'hérédité), d'où l'hormonothérapie si le cancer est RH+.\\n\\nSource : Gynéco L2 IDE version 2025, « Le cancer du sein », Introduction\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les grossesses gémellaires dizygotes ; plus la division de l'œuf est tardive, plus elle pourra aboutir à des siamois\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les grossesses dizygotes (bi-ovulaires) proviennent de deux ovules fécondés : elles sont toujours bichoriales biamniotiques et ne donnent jamais de siamois. Les siamois résultent d'une division très tardive d'un œuf unique (monozygote). (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En cas de dystocies dynamiques, la césarienne s'impose en urgence\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les dystocies dynamiques ont leur traitement propre (correction de l'hypo- ou de l'hypercinésie, antispasmodiques, ocytocine en centre équipé…). La césarienne n'est indiquée qu'en cas d'échec ou de complication, pas d'emblée en urgence.\\n\\nSource : Gynécologie-Obstétrique L3, « Dystocies »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le fibrome utérin est une tumeur bénigne\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le fibrome (myome) utérin est une tumeur bénigne du muscle utérin, souvent associée à la grossesse.\\n\\nSource : Gynécologie-Obstétrique L3 et Gynéco L2 IDE version 2025, « Fibrome et grossesse »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La sécrétion du liquide amniotique est essentiellement fœtale et se fait par voie digestive\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Pendant la grossesse, le liquide amniotique provient surtout des urines fœtales ; la voie digestive (déglutition fœtale) sert à sa résorption, pas à sa sécrétion. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'HTA au cours de la grossesse est la deuxième cause de mortalité maternelle.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai ». Les causes obstétricales directes de décès maternels du cours sont : hémorragies 21 %, avortements à risque 14 %, éclampsies 13 %, travail dystocique 8 %, infection 8 %.\\n\\nSource : Cours de soins obstétricaux 2e année SF, « Généralités sur les SONU » ; Cours Gynéco-Obstétrique 1re année INFAS, « Généralités sur les SONU »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La phase folliculaire est sous la dépendance des œstrogènes\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La phase folliculaire (du début des règles au 13e jour) est dominée par la sécrétion d'œstrogènes par le follicule en croissance ; la phase lutéale est oestro-progestative.\\n\\nSource : Cours Gynéco-Obstétrique 1re année INFAS, « Le cycle menstruel normal »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, deux (2) situations se retrouvent dans le premier retard : lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Retard d'exécution des soins\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Méconnaissance des signes de danger\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Insuffisance de personnel\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Insuffisance de moyens de référence adéquate\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Faible pouvoir de décision de la femme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Méconnaissance des signes de danger ; E. Faible pouvoir de décision de la femme\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"Premier retard (décision de consulter) : méconnaissance des signes de danger, lenteur de la prise de décision, faible pouvoir de décision de la femme. L'insuffisance de moyens de référence relève du 2e retard ; le retard d'exécution des soins et l'insuffisance de personnel relèvent du 3e retard.\\n\\nSource : Cours de soins obstétricaux 2e année SF, « Généralités sur les SONU », Les trois retards\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle est la complication la plus à craindre en cas de mort fœtale in utero ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Infection\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rupture utérine\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Trouble de l'hémostase\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Anémie chez la mère\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Trouble de l'hémostase\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Après une mort fœtale, la complication la plus redoutée est le trouble de la coagulation (fibrinogène < 1,5 g/l, risque d'afibrinogénémie avec hémorragie), surtout après plusieurs semaines de rétention.\\n\\nSource : Gynécologie-Obstétrique L3, chap. 20 « La mort fœtale », Complications\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel soin ne doit pas être prodigué après la réfection de l'épisiotomie ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vérifier la symétrie de la suture.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faire des bains de siège.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Surveiller les signes d'infection.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Informer la patiente sur le traitement.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faire des bains de siège.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Après épisiotomie : toilette vulvaire biquotidienne et après chaque émission d'urine ou de selles, périnée gardé sec, garniture changée souvent, et « ne pas faire de bain de siège ».\\n\\nSource : Gynéco L2 IDE version 2025, « Suites de couches », Soins en cas d'épisiotomie\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle manœuvre est réalisée en cas de rétention de la tête dernière lors d'un accouchement de siège ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Manœuvre de Bracht\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Manœuvre de Lovset\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Manœuvre de Mauriceau\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Attitude de Vermelin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Manœuvre de Mauriceau\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La manœuvre de Mauriceau est indiquée en cas de rétention de la tête dernière dans l'excavation. Bracht sert au dégagement d'une tête déjà basse, Lovset au relèvement des bras ; Vermelin est l'attitude abstentionniste.\\n\\nSource : SONU L3 (2024-2025), « Accouchement du siège », Méthodes interventionnistes\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle de ces présentations est considérée comme hautement dystocique ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Présentation du sommet\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Présentation du bregma\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Présentation du front\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Présentation du siège\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Présentation du front\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La présentation du front est hautement dystocique : son diamètre d'engagement (syncipito-mentonnier, 13,5 cm) ne peut pas franchir le détroit supérieur ; la césarienne est obligatoire.\\n\\nSource : Cours Gynéco-Obstétrique 1re année INFAS, « Présentations fœtales » ; Cours de soins obstétricaux 2e année SF, « Les différentes présentations »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est le degré de procidence où le cordon est extériorisé à la vulve ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Degré I\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Degré II\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Degré III\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Degré IV\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Degré III\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient le degré III pour un cordon extériorisé à la vulve (degrés croissants selon la descente du cordon : dans le vagin, puis à la vulve). (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"A quelle phase du travail peut survenir une dilatation stationnaire ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Phase de latence uniquement\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Phase active uniquement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les deux phases\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Phase de délivrance\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Les deux phases\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Une dilatation stationnaire peut s'observer pendant la phase de latence comme pendant la phase active du travail ; c'est un signe d'alerte (le cours la cite parmi les signes de pré-rupture utérine et d'échec de l'épreuve du travail). (explication partiellement hors cours du projet)\\n\\nSource : Gynéco L2 IDE version 2025, « Rupture utérine », Syndrome de pré-rupture ; Gynécologie-Obstétrique L3, « L'épreuve du travail »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle est l'origine principale du liquide amniotique pendant la grossesse ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Exsudation à travers les membranes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Urines du fœtus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Sueur de la mère\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Transfusion sanguine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Urines du fœtus\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"À partir du 2e trimestre, la principale source du liquide amniotique est la diurèse (urines) du fœtus ; un oligoamnios peut ainsi révéler une anomalie rénale fœtale. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est l'un des objectifs du traitement de la grossesse extra-utérine ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Augmenter le taux de BHCG\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Préserver la fertilité\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Accélérer la croissance du fœtus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Permettre la migration de l'œuf dans l'utérus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Préserver la fertilité\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le traitement de la GEU vise à arrêter l'hémorragie, retirer la grossesse ectopique et, chaque fois que possible, préserver la fertilité (traitement conservateur de la trompe). Augmenter les β-HCG ou faire migrer l'œuf est impossible. (explication hors cours du projet) Remarque : Le cours SONU L2 décrit la conduite à tenir (référence, traitement chirurgical) sans lister les objectifs du traitement.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous recevez dans votre centre de santé urbain une primipare dilatée à 3 cm avec un fœtus présentant une souffrance fœtale aiguë, deux attitudes sont à réaliser : lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hâter l'accouchement par voie basse par une perfusion d'ocytocique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Administrer le sérum glucosé hypertonique à 10%\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Faire une extraction instrumentale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Référer en urgence la parturiente vers un centre obstétrico-chirurgical\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Il n'est pas nécessaire de faire une réanimation néonatale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Administrer le sérum glucosé hypertonique à 10% ; D. Référer en urgence la parturiente vers un centre obstétrico-chirurgical\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"La SFA est une urgence fœtale ; en périphérie, c'est un motif de transfert urgent vers un centre médico-chirurgical (l'accouchement n'est pas imminent à 3 cm). La correction nationale de la Prépa DE (les J) retient aussi le sérum glucosé hypertonique à 10 % comme mesure de réanimation in utero. Les ocytociques aggravent la souffrance fœtale. (explication partiellement hors cours du projet) Remarque : Le sérum glucosé à 10 % n'est pas cité dans le cours.\\n\\nSource : Gynéco L2 IDE version 2025, « La souffrance fœtale aiguë », Attitude thérapeutique\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Deux propositions sont exactes concernant les grossesses gémellaires bi-ovulaires : lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Elle est toujours bi choriale bi amniotique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les fœtus sont toujours de même sexe\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Ce sont des faux jumeaux\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les fœtus sont toujours de sexe différent\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Elle peut donner naissance à des siamois\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Elle est toujours bi choriale bi amniotique ; C. Ce sont des faux jumeaux\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Grossesse bi-ovulaire (dizygote) = faux jumeaux, issus de deux ovules et deux spermatozoïdes : toujours bichoriale biamniotique, fœtus de même sexe ou de sexes différents, jamais de siamois. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Concernant le cordon ombilical : deux assertions sont fausses : lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Il contient 3 vaisseaux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Il contient un nerf\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Il contient deux artères et une veine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Il contient deux veines et une artère\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Il mesure en moyenne 60 cm\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Il contient un nerf ; D. Il contient deux veines et une artère\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Le cordon contient trois vaisseaux : deux artères et une veine (la veine est plus grosse). Il ne contient pas de nerf. Sa longueur normale est de 50 à 70 cm.\\n\\nSource : Cours de soins obstétricaux 2e année SF, « Examen du placenta », Examen du cordon\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le phénomène Transfuseur/Transfusé se retrouve dans une des situations suivantes : laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Chez des jumeaux de sexes différents\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dans la grossesse gémellaire bi ovulaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dans la grossesse gémellaire bi choriale bi amniotique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Dans les grossesses gémellaires mono choriale bi amniotique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Dans les grossesses gémellaires mono choriale bi amniotique\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le syndrome transfuseur-transfusé est propre aux grossesses monochoriales (placenta unique partagé avec anastomoses vasculaires) ; il n'existe pas dans les grossesses bichoriales (bi-ovulaires). (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle de ces propositions est exacte, concernant le placenta\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le cordon ombilical s'insère sur la face maternelle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Il pèse en moyenne 1/6 du poids du fœtus à terme\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La face fœtale est charnue et contient des cotylédons\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Il permet de maintenir la grossesse dès la fécondation de l'œuf\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Il pèse en moyenne 1/6 du poids du fœtus à terme\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le poids du placenta représente environ 1/6 du poids de l'enfant. Le cordon s'insère sur la face fœtale ; les cotylédons sont sur la face maternelle.\\n\\nSource : Cours de soins obstétricaux 2e année SF, « Examen du placenta », Technique\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'une des propositions suivantes ne se retrouve pas dans la présentation de l'épaule négligée : laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le fœtus est le plus souvent vivant\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Elle fait partie des présentations transversales\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"On retrouve une procidence du bras\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Infection ovulaire probable\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Le fœtus est le plus souvent vivant\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans l'épaule négligée, le fœtus est le plus souvent mort ; on retrouve une présentation transversale, une procidence du bras et un risque d'infection ovulaire (membranes rompues).\\n\\nSource : Cours Gynéco-Obstétrique 1re année INFAS, « Présentations fœtales », Épaule négligée\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les présentations suivantes, l'une a pour diamètre d'engagement le diamètre occipito-frontal : laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La Présentation du front\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La Présentation du sommet\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La Présentation du bregma\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La Présentation de la face\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La Présentation du bregma\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Diamètres d'engagement : sommet = sous-occipito-bregmatique (9,5 cm), bregma = occipito-frontal (12 cm), front = syncipito-mentonnier (13,5 cm), face = sous-mento-bregmatique (9,5 cm).\\n\\nSource : Cours Gynéco-Obstétrique 1re année INFAS, « Présentations fœtales »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__36\",\n       \"num\": \"37\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"A quel diagnostic pensez-vous ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"HTA gravidique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Pré-éclampsie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"HTA chronique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Pré-éclampsie surajoutée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Pré-éclampsie surajoutée\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Mme X est hypertendue connue (HTA chronique) et présente une protéinurie ++ : c'est une pré-éclampsie surajoutée (HTA chronique + protéinurie significative). Les céphalées et le flou visuel sont des signes de sévérité.\\n\\nSource : SONU Licence 2 SFM (2025-2026), « HTA et grossesse », Types d'HTA\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__37\",\n       \"num\": \"38\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"15 minutes après son admission, elle présente une crise convulsive. Il s'agit d'une\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Pré-éclampsie sévère avec signe d'éclampsisme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Crise hystérie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Crise d'éclampsie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Crise d'épilepsie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Crise d'éclampsie\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Une crise convulsive chez une femme en pré-éclampsie est une éclampsie. Toute convulsion en cours de grossesse est traitée comme une éclampsie jusqu'à preuve du contraire.\\n\\nSource : Cours de soins obstétricaux 2e année SF, « HTA / éclampsie et grossesse »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__38\",\n       \"num\": \"39\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"N'ayant jamais assisté à un tel événement, vous contactez votre médecin référant qui vous donne des instructions. Parmi ces instructions, vous décidez de suivre deux, lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Appeler à l'aide\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Mettre une compresse dans la bouche de la patiente\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La mettre en position latérale de sécurité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'attacher au lit\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Administrer 5 cc de valium en IM\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Appeler à l'aide ; C. La mettre en position latérale de sécurité\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Devant une patiente qui convulse : mobiliser d'urgence l'équipe (appeler à l'aide) et la mettre en position latérale de sécurité pour éviter l'inhalation. On n'introduit rien de force dans la bouche (seulement canule de Guédel ou compresses pour éviter la morsure), on ne l'attache pas.\\n\\nSource : Cours de soins obstétricaux 2e année SF, « HTA / éclampsie », Prise en charge d'une patiente en état convulsif\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__39\",\n       \"num\": \"40\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Après avoir validé votre décision, il vous demande de faire un traitement pré-transfert. Quelle molécule allez-vous utiliser en première intention ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Valium\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Célestène\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Sulfate de magnésium\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Gardénal\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Sulfate de magnésium\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le sulfate de magnésium est l'anticonvulsivant de première intention (le diazépam est l'alternative).\\n\\nSource : Cours de soins obstétricaux 2e année SF, « Recommandations pour l'utilisation du sulfate de magnésium » ; ECLAMPSIE (diaporama du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__40\",\n       \"num\": \"41\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Quelle est la dose de charge à administrer en intramusculaire ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"4 grammes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"5 grammes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"10 grammes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"14 grammes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 10 grammes\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Dose de charge : 4 g de sulfate de magnésium à 20 % en IV lente, puis 5 g en IM profonde dans chaque fesse, soit 10 g au total en IM (avec 1 ml de lidocaïne à 2 %). Remarque : La dose de charge totale (IV + IM) est de 14 g ; la question porte sur la seule partie IM (10 g).\\n\\nSource : Cours de soins obstétricaux 2e année SF, « Recommandations pour l'utilisation du sulfate de magnésium », Dose de charge\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__41\",\n       \"num\": \"42\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"En attendant l'ambulance pour son transfert, vous décidez de surveiller la patiente. Quels sont les deux paramètres les plus importants de cette surveillance ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La fréquence cardiaque\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La température\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La fréquence respiratoire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'état de conscience\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La tension artérielle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. La fréquence respiratoire ; D. L'état de conscience\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Sous sulfate de magnésium, avant chaque dose, on vérifie la fréquence respiratoire (≥ 16/min), les réflexes rotuliens et la diurèse (≥ 30 ml/h) ; l'état de conscience fait partie des éléments de surveillance de l'HTA. Risque principal : dépression respiratoire.\\n\\nSource : Cours de soins obstétricaux 2e année SF, « Recommandations pour l'utilisation du sulfate de magnésium » ; SONU Licence 2 SFM (2025-2026), « Éléments de surveillance »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__42\",\n       \"num\": \"43\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"La patiente est admise 3 heures de temps après à l'Hôpital général de référence. D'après vous quelle serait la conduite à tenir dans le centre de référence ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hospitaliser la patiente pour une meilleure surveillance de la grossesse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Préconiser un déclenchement en vue d'un accouchement par voie basse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Réaliser une césarienne en urgence\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Faire une maturation pulmonaire et prévoir l'intervention à la 36 SA\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Réaliser une césarienne en urgence\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'évacuation utérine est le seul traitement curatif de l'éclampsie ; après une crise d'éclampsie chez une femme stabilisée au centre de référence, l'accouchement doit être obtenu rapidement ; la correction nationale de la Prépa DE (les J) retient la césarienne en urgence (on n'attend pas 36 SA).\\n\\nSource : ECLAMPSIE (diaporama du projet), « Conclusion » ; Cours de soins obstétricaux 2e année SF, « CAT devant une éclampsie »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__43\",\n       \"num\": \"44\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Elle donne naissance à un prématuré pesant 1300 grammes, APGAR 5,6 : il s'agit d'un(e)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Bon état initial\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"État de mort apparente\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dépression respiratoire immédiate\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Dépression respiratoire immédiate\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Un score d'Apgar de 5-6 traduit un nouveau-né en difficulté sans mort apparente : dépression respiratoire (état intermédiaire). Le cours indique de réanimer immédiatement si l'Apgar est ≤ 7. (explication partiellement hors cours du projet)\\n\\nSource : SONU Licence 2 SFM (2025-2026), « Soins à l'accouchée et au nouveau-né », Appréciation du score d'Apgar\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__44\",\n       \"num\": \"45\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Quels seront les deux gestes à réaliser dans ce cas\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Désobstruction des voies aériennes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Massage cardiaque externe\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Administrer d'adrénaline\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Ventilation externe\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Intubation trachéale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Désobstruction des voies aériennes ; D. Ventilation externe\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"Les premiers gestes de réanimation sont la désobstruction des voies aériennes (aspiration bouche puis nez) puis la ventilation. Le massage cardiaque, l'adrénaline et l'intubation ne viennent qu'ensuite, si nécessaire.\\n\\nSource : Cours Gynéco-Obstétrique 1re année INFAS, « Soins au nouveau-né », Désobstruction ; Cours de soins obstétricaux 2e année SF, « Surveillance du nouveau-né »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__45\",\n       \"num\": \"46\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Lors de la surveillance, Mme X demande au Maïeuticien en salle de réveil de surélever la tête du lit car elle arrive difficilement à respirer. Elle présente une toux avec des crachats mêlés de sang. A quel diagnostic pensez-vous ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une tuberculose pulmonaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une crise d'asthme\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un œdème aigu du poumon\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une embolie pulmonaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Un œdème aigu du poumon\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Dyspnée (orthopnée : elle demande à surélever la tête), toux avec crachats mousseux ou sanglants chez une pré-éclamptique : c'est un œdème aigu du poumon, complication maternelle de l'HTA.\\n\\nSource : SONU Licence 2 SFM (2025-2026), « HTA et grossesse », Complications maternelles (OAP)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__46\",\n       \"num\": \"47\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Quel geste important aurait dû être réalisé par la sage-femme ayant reçu la patiente dans le centre de santé urbain et qui aurait pu prévenir cette complication\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La prise d'une bonne voie veineuse avant son évacuation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La surveillance de la tension artérielle, de la fréquence respiratoire et du pouls régulièrement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La mise en place d'une sonde urinaire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La mise en place d'une canule de GUEDEL dans la bouche\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La mise en place d'une sonde urinaire\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La sonde urinaire à demeure fait partie de la mise en condition de l'éclamptique : elle permet de surveiller la diurèse heure par heure et d'adapter les apports liquidiens, ce qui aide à prévenir la surcharge responsable de l'OAP. (explication partiellement hors cours du projet)\\n\\nSource : Cours de soins obstétricaux 2e année SF, « Prise en charge d'une patiente en état convulsif » ; SONU Licence 2 SFM (2025-2026), « Éléments de surveillance »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__47\",\n       \"num\": \"48\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Le protocole mis en place permet de stabiliser la patiente. 1 heure après, l'aide-soignante voulant nettoyer la patiente constate que tout les draps sont imbibés de sang et vous alerte ; votre examen retrouve une voie non perméable, TA : 08/06 cmHg et un pouls à 112 BPM. Il s'agit probablement d'une hémorragie du post-partum immédiat par\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rétention placentaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Coagulopathie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Déchirure du col\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Atonie utérine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Atonie utérine\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Draps imbibés de sang, hypotension (8/6) et tachycardie (112) dans le post-partum immédiat : HPPI avec choc. La première cause à évoquer est l'atonie utérine.\\n\\nSource : Gynécologie-Obstétrique L3, « CAT devant une HPP » ; SONU L3 (2024-2025), « Prise en charge du choc »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__48\",\n       \"num\": \"49\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Quelle serait votre conduite à tenir en urgence\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'ablation de l'utérus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Perméabiliser de la voie veineuse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Faire une délivrance artificielle\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Mettre un tamponnement intra-utérin par ballonnet (UBT)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Perméabiliser de la voie veineuse\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La voie veineuse n'est plus perméable : la priorité est de reprendre un abord veineux (2 voies de gros calibre) pour le remplissage et les utérotoniques, avant les autres gestes.\\n\\nSource : SONU L3 (2024-2025), « Prise en charge du choc » ; Cours de soins obstétricaux 2e année SF, « CAT devant une HPP » (prendre une bonne voie veineuse)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__49\",\n       \"num\": \"50\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Tout se passe bien et après 5 jours d'hospitalisation vous prévoyez sa sortie après un counselling en planification familiale. Quelle méthode peut-elle utiliser avant sa sortie de l'hôpital ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le dispositif intra-utérin\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les injectables à seul progestatif\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'implant\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les injectables combinés\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. L'implant\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"À J5 du post-partum, après pré-éclampsie et chez une femme qui allaite : les méthodes œstroprogestatives (injectables combinés) sont contre-indiquées (catégorie 4), le DIU est déconseillé entre 48 h et 4 semaines (catégorie 3), les injectables progestatifs sont en catégorie 3 avant 6 semaines d'allaitement. L'implant (catégorie 2) peut être posé avant la sortie.\\n\\nSource : Cours SR/PF L2 (Document SSR), chap. 17, « Critères d'éligibilité appliqués au post-partum »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
